answer:
Recover the longest contiguous prefix that passes all checks, returning its end byte offset. Stop immediately at the first incomplete or invalid record—never search ahead. A passing CRC is not proof that a record is intact or durable.

All integer fields below are decoded little-endian. Supply the declared CRC-32C function using the writer’s checksum conventions.

```cpp
// recover.cpp
#include <array>
#include <cstddef>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <limits>
#include <span>
#include <stdexcept>
#include <vector>

// Supplied separately; returns the finalized CRC-32C.
std::uint32_t crc32c(std::span<const std::uint8_t> bytes);

static bool read_exact(std::ifstream& file, std::uint8_t* dst,
                       std::size_t size) {
    if (size == 0) return true;
    file.read(reinterpret_cast<char*>(dst),
              static_cast<std::streamsize>(size));
    if (file.bad() || (file.fail() && !file.eof()))
        throw std::runtime_error("log read error");
    return file.gcount() == static_cast<std::streamsize>(size);
}

static std::uint64_t decode_le(const std::uint8_t* p,
                               unsigned size) {
    std::uint64_t value = 0;
    for (unsigned i = 0; i < size; ++i)
        value |= std::uint64_t{p[i]} << (8u * i);
    return value;
}

// Requires a stable binary file positioned at byte zero.
// Returns a byte offset, not the stream's current read position.
std::uint64_t recover(std::ifstream& file) {
    constexpr std::uint32_t max_payload = 1024u * 1024u;
    constexpr auto u64max =
        std::numeric_limits<std::uint64_t>::max();

    std::uint64_t last_valid = 0;
    std::uint64_t expected = 0;
    bool exhausted = false;
    std::array<std::uint8_t, 12> header{};
    std::array<std::uint8_t, 4> checksum{};
    std::vector<std::uint8_t> covered;

    for (;;) {
        // No successor is permitted after UINT64_MAX.
        if (exhausted) return last_valid;
        if (!read_exact(file, header.data(), header.size()))
            return last_valid;

        const auto length = static_cast<std::uint32_t>(
            decode_le(header.data(), 4));
        const auto sequence = decode_le(header.data() + 4, 8);
        if (length > max_payload || sequence != expected)
            return last_valid;

        // Widen before computing total record size.
        const std::uint64_t record_bytes =
            std::uint64_t{length} + 16u;
        if (last_valid > u64max - record_bytes)
            throw std::overflow_error("byte offset exceeds uint64_t");

        covered.resize(static_cast<std::size_t>(length) + 8u);
        for (unsigned i = 0; i < 8; ++i)
            covered[i] = header[4 + i];

        if (!read_exact(file, covered.data() + 8, length))
            return last_valid;
        if (!read_exact(file, checksum.data(), checksum.size()))
            return last_valid;

        const auto stored = static_cast<std::uint32_t>(
            decode_le(checksum.data(), 4));
        if (crc32c(std::span<const std::uint8_t>(
                covered.data(), covered.size())) != stored)
            return last_valid;

        // Advance only after the complete record passes every check.
        last_valid += record_bytes;
        if (expected == u64max)
            exhausted = true;
        else
            ++expected;
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: recover LOGFILE\n";
        return 1;
    }
    try {
        std::ifstream file(argv[1], std::ios::binary);
        if (!file) throw std::runtime_error("cannot open log");
        std::cout << recover(file) << '\n';
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
```

Build with `c++ -std=c++20 -O2 recover.cpp supplied_crc32c.cpp -o recover`; run `./recover log.bin`. The supplied source must define the declared function. Recovery requires no concurrent file modification and does not truncate the file.

Correctness: initially the accepted prefix is empty and the expected sequence is zero. Each successful iteration consumes exactly `16 + length` bytes, checks the next sequence and CRC over the original eight encoded sequence bytes plus payload, and only then advances the accepted boundary. Every failing check returns immediately with that boundary unchanged, so no later plausible record is considered.

Empty files return zero. Short headers, payloads, and checksums return the preceding boundary; zero-length payloads are allowed. Length validation bounds the buffer to 1 MiB plus eight bytes, offset addition is checked, decoding shifts are at most 56 bits, and sequence advancement never wraps. Genuine I/O errors are reported rather than treated as torn tails.

Recovery guarantees the longest check-valid contiguous prefix, not the original intact prefix: CRC collisions can admit corrupted records, and the length is outside CRC coverage. Missing suffix records cannot be reconstructed, and checksum validity alone cannot establish which writes were committed or durable.
